SELECT COUNT(*) AS cancelled_orders
FROM orders
WHERE status = 'cancelled';

SELECT COUNT(*) AS total_mall_shops
FROM sellers
WHERE is_mall = TRUE;

SELECT COUNT(*) AS total_percent_vouchers
FROM vouchers
WHERE discount_type = 'percent';

SELECT COUNT(*)
FROM categories
WHERE parent_id IS NULL;

SELECT COUNT(*) AS total_customers
FROM customers
WHERE province IN ('Hà Nội', 'HN', 'Ha Noi', 'Hanoi');

SELECT COUNT(*) AS total_five_star_reviews
FROM reviews
WHERE rating = 5;

SELECT COUNT(*) AS non_standard_customer_count
FROM customers
WHERE province IN ('HN', 'Ha Noi', 'Hanoi', 'TP.HCM', 'Sài Gòn', 'HCM', 'Ho Chi Minh');
